import { mkdir, readFile, rename, rm, stat, writeFile } from "node:fs/promises";
import { basename, dirname, relative, resolve } from "node:path";
import { randomUUID } from "node:crypto";
import { canonicalJson, compareCodePoint, sha256, treeSha256 } from "./canonicalize.mjs";
import { fail } from "./errors.mjs";
import { assertArtifactIntegrity } from "./check.mjs";
import { buildHeadingIndex } from "./heading-index.mjs";

const COMMON_RUNTIME_ARTIFACTS = new Map([
  ["scripts/runtime/common.mjs", "src/runtime/common.mjs"],
  ["scripts/runtime/integrity.mjs", "src/runtime/integrity.mjs"],
]);

function withGeneratedMarker(entry, logicalSource) {
  const marker = `<!-- generated; do not edit; source: ${logicalSource}; receipt: .skill-rails-build.json -->`;
  if (!entry.startsWith("---\n")) fail("ENTRY_INVALID", `${logicalSource} must start with YAML frontmatter.`, "Add a closed skill frontmatter block.");
  const end = entry.indexOf("\n---\n", 4);
  if (end < 0) fail("ENTRY_INVALID", `${logicalSource} has no closing YAML frontmatter delimiter.`, "Close the frontmatter with --- on its own line.");
  return `${entry.slice(0, end + 5)}${marker}\n${entry.slice(end + 5)}`;
}

function artifactPathForModule(id) {
  return `references/${id}.md`;
}

function generatedTargetConfig(graph, item) {
  const { target } = item;
  return {
    schemaVersion: 1,
    packageId: graph.manifest.packageId,
    packageVersion: graph.manifest.packageVersion,
    targetId: target.targetId,
    mode: target.mode,
    imports: target.imports.map((id) => ({ id, path: artifactPathForModule(id) })),
    headingIndex: target.headingIndex ? `references/${target.headingIndex}.index.json` : null,
    fallbackReference: target.fallbackModule ? "references/fallback.md" : null,
    domainConfig: target.mode === "prose" ? null : "config/domain.json",
    domainConfigSchema: target.mode === "prose" ? null : "config/domain.schema.json",
    packet: target.packet ? "config/packet.json" : null,
    observer: target.observer ? "scripts/domain/observer.mjs" : null,
    renderer: target.renderer ? "scripts/domain/renderer.mjs" : null,
    answerContract: target.mode === "prose" ? null : `contracts/${basename(target.answerContract)}`,
    declaredInputs: target.declaredInputs ?? [],
    declaredOutput: target.declaredOutput ?? null,
    outputMode: target.outputMode ?? null,
    regionBootstrap: target.regionBootstrap ?? null,
  };
}

function addSource(sources, id, item) {
  sources.push({ id, path: item.path, sha256: sha256(item.bytes) });
}

export async function planTargetBuild(graph, targetId) {
  const item = graph.targets.get(targetId);
  if (!item) fail("TARGET_NOT_FOUND", `Unknown targetId: ${targetId}`, "Choose an exact targetId declared by the source package.");
  const artifacts = new Map();
  const sources = [];
  addSource(sources, "source-package", { path: relative(graph.rootReal, graph.manifestPath).replaceAll("\\", "/"), bytes: graph.manifestBytes });
  addSource(sources, `target:${targetId}`, { path: item.path, bytes: item.bytes });
  const entry = item.files.get("entry");
  addSource(sources, "entry", entry);
  artifacts.set("SKILL.md", Buffer.from(withGeneratedMarker(entry.text, entry.path), "utf8"));

  for (const id of item.target.imports) {
    const module = graph.modules.get(id);
    addSource(sources, `module:${id}`, module);
    artifacts.set(artifactPathForModule(id), module.bytes);
  }
  if (item.target.headingIndex) {
    const module = graph.modules.get(item.target.headingIndex);
    artifacts.set(`references/${item.target.headingIndex}.index.json`, buildHeadingIndex(module));
  }
  if (item.target.fallbackModule) {
    const module = graph.modules.get(item.target.fallbackModule);
    if (!sources.some((source) => source.id === `module:${module.id}`)) addSource(sources, `module:${module.id}`, module);
    artifacts.set("references/fallback.md", module.bytes);
  }

  artifacts.set("config/target.json", Buffer.from(`${canonicalJson(generatedTargetConfig(graph, item))}\n`, "utf8"));
  if (item.target.mode !== "prose") {
    const mappings = [
      ["domainConfig", "config/domain.json"],
      ["domainConfigSchema", "config/domain.schema.json"],
      ...(item.target.packet ? [["packet", "config/packet.json"]] : []),
      ["renderer", "scripts/domain/renderer.mjs"],
      ["answerContract", `contracts/${basename(item.target.answerContract)}`],
    ];
    if (item.target.observer) mappings.push(["observer", "scripts/domain/observer.mjs"]);
    for (const [role, destination] of mappings) {
      const source = item.files.get(role);
      addSource(sources, role, source);
      artifacts.set(destination, source.bytes);
    }
  }

  const runtimeArtifacts = new Map(COMMON_RUNTIME_ARTIFACTS);
  runtimeArtifacts.set("scripts/run.mjs", item.target.mode === "prose" ? "src/runtime/run-check.mjs" : item.target.mode === "record-only" ? "src/runtime/run-record.mjs" : "src/runtime/run.mjs");
  if (item.target.mode === "prepare-record") {
    runtimeArtifacts.set("scripts/runtime/prepare.mjs", "src/runtime/prepare.mjs");
  }
  if (item.target.mode !== "prose") {
    runtimeArtifacts.set("scripts/runtime/exchange.mjs", "src/runtime/exchange.mjs");
    runtimeArtifacts.set("scripts/runtime/record.mjs", "src/runtime/record.mjs");
  }
  if (item.target.mode === "record-only") runtimeArtifacts.set("scripts/runtime/initialize-record.mjs", "src/runtime/initialize-record.mjs");
  for (const [destination, source] of runtimeArtifacts) {
    const bytes = await readFile(resolve(graph.repositoryRoot, source));
    artifacts.set(destination, bytes);
    addSource(sources, `runtime:${destination}`, { path: source, bytes });
  }
  const contractNames = ["build-receipt.schema.json"];
  if (item.target.mode !== "prose") contractNames.push("record-exchange.schema.json");
  if (item.target.packet) contractNames.push("packet-kernel.schema.json", "observed-facts.schema.json", "prepared-work.schema.json");
  for (const name of contractNames) {
    const sourcePath = `contracts/${name}`;
    const bytes = await readFile(resolve(graph.repositoryRoot, sourcePath));
    artifacts.set(sourcePath, bytes);
    addSource(sources, `contract:${name}`, { path: sourcePath, bytes });
  }

  const artifactRows = [...artifacts.entries()]
    .sort(([left], [right]) => compareCodePoint(left, right))
    .map(([path, bytes]) => ({ path, sha256: sha256(bytes) }));
  const receipt = {
    schemaVersion: 1,
    coreVersion: graph.coreVersion,
    packageId: graph.manifest.packageId,
    packageVersion: graph.manifest.packageVersion,
    targetId,
    sources: sources.sort((a, b) => compareCodePoint(a.path, b.path) || compareCodePoint(a.id, b.id)),
    artifacts: artifactRows,
    imports: [...item.target.imports],
    treeSha256: treeSha256(artifacts),
  };
  return { graph, item, artifacts, receipt, receiptBytes: Buffer.from(`${canonicalJson(receipt)}\n`, "utf8") };
}

async function exists(path) {
  try { await stat(path); return true; } catch (error) { if (error?.code === "ENOENT") return false; throw error; }
}

async function materialize(plan, destination) {
  const exact = resolve(destination);
  const parent = dirname(exact);
  await mkdir(parent, { recursive: true });
  if (await exists(exact)) {
    await assertArtifactIntegrity(exact, "GENERATED_ARTIFACT_MODIFIED");
  }
  const token = randomUUID();
  const stage = resolve(parent, `.${basename(exact)}.stage-${token}`);
  const backup = resolve(parent, `.${basename(exact)}.backup-${token}`);
  try {
    await mkdir(stage);
    for (const [path, bytes] of [...plan.artifacts.entries()].sort(([a], [b]) => compareCodePoint(a, b))) {
      const output = resolve(stage, ...path.split("/"));
      await mkdir(dirname(output), { recursive: true });
      await writeFile(output, bytes);
    }
    await writeFile(resolve(stage, ".skill-rails-build.json"), plan.receiptBytes);
    await assertArtifactIntegrity(stage);
    if (await exists(exact)) await rename(exact, backup);
    try {
      await rename(stage, exact);
    } catch (error) {
      if (await exists(backup)) await rename(backup, exact);
      throw error;
    }
    await rm(backup, { recursive: true, force: true });
  } finally {
    await rm(stage, { recursive: true, force: true });
  }
  return { targetId: plan.receipt.targetId, output: exact, treeSha256: plan.receipt.treeSha256 };
}

export async function buildTargets(graph, options) {
  const selected = options.target ? [options.target] : [...graph.targets.keys()].sort(compareCodePoint);
  if (options.target && !options.out) fail("ARGUMENT_INVALID", "--target requires --out.", "Provide one exact target output directory.");
  if (!options.target && !options.outRoot) fail("ARGUMENT_INVALID", "Building all targets requires --out-root.", "Provide the distribution root.");
  const plans = [];
  for (const targetId of selected) plans.push(await planTargetBuild(graph, targetId));
  const outputs = [];
  for (const plan of plans) {
    const destination = options.target ? options.out : resolve(options.outRoot, "skills", plan.receipt.targetId);
    outputs.push(await materialize(plan, destination));
  }
  return { schemaVersion: 1, status: "BUILT", outputs };
}

import { readFile } from "node:fs/promises";
import { dirname, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { canonicalJson, canonicalText, compareCodePoint, sha256 } from "./canonicalize.mjs";
import { fail } from "./errors.mjs";
import { assertNoCaseFoldCollisions, normalizeRelativePath, resolveContainedFile, resolveContainedFileFrom, sourceRootFor } from "./paths.mjs";

const repositoryRoot = resolve(dirname(fileURLToPath(import.meta.url)), "../..");

export function validateJsonSchema(value, schema, at = "$") {
  const errors = [];
  const visit = (current, rule, path) => {
    if (rule.oneOf) {
      const candidates = rule.oneOf.map((candidate) => {
        const before = errors.length;
        visit(current, candidate, path);
        const result = errors.splice(before);
        return result;
      });
      const passing = candidates.filter((candidate) => candidate.length === 0).length;
      if (passing !== 1) errors.push(`${path} must match exactly one allowed shape`);
      return;
    }
    if (Object.hasOwn(rule, "const") && canonicalJson(current) !== canonicalJson(rule.const)) errors.push(`${path} must equal ${JSON.stringify(rule.const)}`);
    if (rule.enum && !rule.enum.some((item) => canonicalJson(item) === canonicalJson(current))) errors.push(`${path} is not an allowed value`);
    if (rule.type) {
      const actual = current === null ? "null" : Array.isArray(current) ? "array" : Number.isInteger(current) ? "integer" : typeof current;
      const typeMatches = rule.type === actual || (rule.type === "number" && typeof current === "number");
      if (!typeMatches) {
        errors.push(`${path} must be ${rule.type}`);
        return;
      }
    }
    if (typeof current === "string") {
      if (rule.minLength !== undefined && current.length < rule.minLength) errors.push(`${path} is too short`);
      if (rule.pattern && !new RegExp(rule.pattern, "u").test(current)) errors.push(`${path} does not match ${rule.pattern}`);
    }
    if (typeof current === "number" && rule.minimum !== undefined && current < rule.minimum) errors.push(`${path} is below minimum`);
    if (Array.isArray(current)) {
      if (rule.minItems !== undefined && current.length < rule.minItems) errors.push(`${path} has too few items`);
      if (rule.uniqueItems) {
        const keys = current.map(canonicalJson);
        if (new Set(keys).size !== keys.length) errors.push(`${path} has duplicate items`);
      }
      if (rule.items) current.forEach((item, index) => visit(item, rule.items, `${path}[${index}]`));
    }
    if (current && typeof current === "object" && !Array.isArray(current)) {
      const keys = Object.keys(current);
      if (rule.minProperties !== undefined && keys.length < rule.minProperties) errors.push(`${path} has too few properties`);
      for (const required of rule.required ?? []) if (!Object.hasOwn(current, required)) errors.push(`${path}.${required} is required`);
      if (rule.propertyNames?.pattern) {
        const pattern = new RegExp(rule.propertyNames.pattern, "u");
        for (const key of keys) if (!pattern.test(key)) errors.push(`${path} property ${key} is invalid`);
      }
      for (const key of keys) {
        if (rule.properties?.[key]) visit(current[key], rule.properties[key], `${path}.${key}`);
        else if (rule.additionalProperties === false) errors.push(`${path}.${key} is not allowed`);
        else if (rule.additionalProperties && typeof rule.additionalProperties === "object") visit(current[key], rule.additionalProperties, `${path}.${key}`);
      }
    }
  };
  visit(value, schema, at);
  return errors;
}

export async function readJsonFile(path, logicalPath = path) {
  const bytes = await readFile(path);
  const text = canonicalText(bytes, logicalPath);
  let value;
  try {
    value = JSON.parse(text);
  } catch (error) {
    fail("JSON_INVALID", `${logicalPath} is not valid JSON: ${error.message}`, "Correct the canonical JSON source.");
  }
  assertNoDuplicateJsonKeys(text, logicalPath);
  return { value, text, bytes: Buffer.from(text, "utf8") };
}

function assertNoDuplicateJsonKeys(text, logicalPath) {
  let index = 0;
  const whitespace = () => { while (/\s/u.test(text[index] ?? "")) index += 1; };
  const string = () => {
    const start = index;
    index += 1;
    while (index < text.length) {
      if (text[index] === "\\") { index += 2; continue; }
      if (text[index] === '"') { index += 1; return JSON.parse(text.slice(start, index)); }
      index += 1;
    }
    return "";
  };
  const value = () => {
    whitespace();
    if (text[index] === "{") {
      index += 1; whitespace();
      const keys = new Set();
      while (text[index] !== "}") {
        const key = string();
        if (keys.has(key)) fail("JSON_KEY_COLLISION", `${logicalPath} repeats object key ${JSON.stringify(key)}.`, "Keep each canonical JSON key exactly once.");
        keys.add(key); whitespace(); index += 1; value(); whitespace();
        if (text[index] === ",") { index += 1; whitespace(); } else break;
      }
      index += 1; return;
    }
    if (text[index] === "[") {
      index += 1; whitespace();
      while (text[index] !== "]") { value(); whitespace(); if (text[index] === ",") { index += 1; whitespace(); } else break; }
      index += 1; return;
    }
    if (text[index] === '"') { string(); return; }
    while (index < text.length && !/[\s,}\]]/u.test(text[index])) index += 1;
  };
  value();
}

async function readContract(name) {
  return (await readJsonFile(resolve(repositoryRoot, "contracts", name), `contracts/${name}`)).value;
}

function assertSchema(value, schema, label) {
  const errors = validateJsonSchema(value, schema);
  if (errors.length) fail("SCHEMA_INVALID", `${label} violates its closed schema.`, "Correct the canonical source fields.", errors);
}

export async function loadSourceGraph(manifestPath) {
  const { manifestReal, rootReal } = await sourceRootFor(manifestPath);
  const manifestRead = await readJsonFile(manifestReal, relative(rootReal, manifestReal).replaceAll("\\", "/"));
  if (manifestRead.value?.schemaVersion !== 1) fail("UNSUPPORTED_VERSION", "The source package schemaVersion is not supported.", "Use source package schemaVersion 1.");
  assertSchema(manifestRead.value, await readContract("source-package.schema.json"), "source package");
  const manifest = manifestRead.value;
  assertNoCaseFoldCollisions(Object.keys(manifest.modules), "module IDs");
  assertNoCaseFoldCollisions(Object.keys(manifest.targets), "target aliases");

  const modules = new Map();
  const sourcePathSpellings = [];
  for (const [id, sourcePath] of Object.entries(manifest.modules).sort(([a], [b]) => compareCodePoint(a, b))) {
    const resolved = await resolveContainedFile(rootReal, sourcePath, `module ${id}`);
    const text = canonicalText(await readFile(resolved.physical), resolved.normalized);
    modules.set(id, { id, path: resolved.normalized, physical: resolved.physical, text, bytes: Buffer.from(text, "utf8") });
    sourcePathSpellings.push(resolved.normalized);
  }

  const targetSchema = await readContract("target.schema.json");
  const targets = new Map();
  for (const [alias, targetPath] of Object.entries(manifest.targets).sort(([a], [b]) => compareCodePoint(a, b))) {
    const resolvedTarget = await resolveContainedFile(rootReal, targetPath, `target ${alias}`);
    const targetRead = await readJsonFile(resolvedTarget.physical, resolvedTarget.normalized);
    if (targetRead.value?.schemaVersion !== 1) fail("UNSUPPORTED_VERSION", `Target ${alias} uses an unsupported schemaVersion.`, "Use target schemaVersion 1.");
    assertSchema(targetRead.value, targetSchema, `target ${alias}`);
    const target = targetRead.value;
    if (targets.has(target.targetId)) fail("TARGET_COLLISION", `Duplicate targetId: ${target.targetId}`, "Give every target one unique ID.");
    for (const imported of target.imports) if (!modules.has(imported)) fail("IMPORT_MISSING", `${target.targetId} imports missing module ${imported}.`, "Declare the module or correct the target imports.");
    if (target.headingIndex && !target.imports.includes(target.headingIndex)) fail("HEADING_INDEX_UNDECLARED", `${target.targetId} headingIndex is not an imported module: ${target.headingIndex}.`, "Import the exact module selected for the generated heading index.");
    if (target.fallbackModule && !modules.has(target.fallbackModule)) fail("IMPORT_MISSING", `${target.targetId} names missing fallback module ${target.fallbackModule}.`, "Declare the fallback module.");

    const files = new Map();
    const targetRootReal = dirname(resolvedTarget.physical);
    const addFile = async (role, path) => {
      const resolved = await resolveContainedFileFrom(rootReal, targetRootReal, path, `${target.targetId} ${role}`);
      const text = canonicalText(await readFile(resolved.physical), resolved.normalized);
      files.set(role, { role, path: resolved.normalized, physical: resolved.physical, text, bytes: Buffer.from(text, "utf8") });
      sourcePathSpellings.push(resolved.normalized);
    };
    await addFile("entry", target.entry);
    if (target.mode !== "prose") {
      await addFile("domainConfig", target.domainConfig);
      await addFile("domainConfigSchema", target.domainConfigSchema);
      if (target.packet) await addFile("packet", target.packet);
